<div class="right_col" role="main"><div class="d-flex justify-content-between mb-3"><h2>Admission Lotteries</h2><a class="btn btn-primary" href="<?= base_url('school/admission/lotteries/create') ?>">Create lottery</a></div><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table table-hover"><thead><tr><th>Name</th><th>Revision</th><th>Seats</th><th>Waiting</th><th>Candidates</th><th>Status</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><a href="<?= base_url('school/admission/lotteries/'.$item->token) ?>"><?= esc($item->name) ?></a></td><td><?= $item->revision ?></td><td><?= $item->seat_count ?></td><td><?= $item->waiting_count ?></td><td><?= $item->candidate_count ?></td><td><?= esc(ucfirst($item->status)) ?></td></tr><?php endforeach ?><?php if(!$items): ?><tr><td colspan="6" class="text-center text-muted">No lotteries yet.</td></tr><?php endif ?></tbody></table></div></div></div>
